<script setup lang="ts">
import {ref} from 'vue';import {api,fmt,date} from '../api'
defineProps<{athletes:any[]}>();const leftAthlete=ref(''),rightAthlete=ref(''),leftModels=ref<any[]>([]),rightModels=ref<any[]>([]),left=ref(''),right=ref(''),result=ref<any>(null),error=ref('')
async function load(side:string){try{if(side==='left'){leftModels.value=await api(`/athletes/${leftAthlete.value}/models`);left.value=''}else{rightModels.value=await api(`/athletes/${rightAthlete.value}/models`);right.value=''}result.value=null}catch(e:any){error.value=e.message}}
async function compare(){error.value='';try{result.value=await api(`/model-comparison?left=${left.value}&right=${right.value}`)}catch(e:any){error.value=e.message}}
</script>
<template><div class="page-heading"><div><p class="eyebrow">LEGGERE LE DIFFERENZE</p><h1>Confronta due atleti</h1><p>Parametri matematici, contesto dei dati e limiti di comparabilità.</p></div></div><p class="error" v-if="error">{{error}}</p><div class="card form-grid"><label>Primo atleta<select v-model="leftAthlete" @change="load('left')"><option value="">Seleziona…</option><option v-for="a in athletes" :value="a.id">{{a.first_name}} {{a.last_name}}</option></select></label><label>Versione<select v-model="left"><option value="">Seleziona…</option><option v-for="m in leftModels" :value="m.id">{{date(m.created_at)}} · {{m.id.slice(0,8)}}</option></select></label><label>Secondo atleta<select v-model="rightAthlete" @change="load('right')"><option value="">Seleziona…</option><option v-for="a in athletes" :value="a.id" :disabled="a.id===leftAthlete">{{a.first_name}} {{a.last_name}}</option></select></label><label>Versione<select v-model="right"><option value="">Seleziona…</option><option v-for="m in rightModels" :value="m.id">{{date(m.created_at)}} · {{m.id.slice(0,8)}}</option></select></label><button :disabled="!left||!right||leftAthlete===rightAthlete" @click="compare">Confronta parametri</button></div><template v-if="result"><p class="warning" v-if="!result.compatible">Configurazioni diverse: confronto non direttamente equivalente.</p><div class="card"><table><thead><tr><th>Parametro</th><th>Primo atleta · media / SD tra tratti</th><th>Secondo atleta · media / SD tra tratti</th><th>Lettura</th></tr></thead><tbody><tr v-for="(key,i) in ['K','L','tau']"><td>{{key}} · {{key==='K'?'bpm/W':'s'}}</td><td>{{fmt(result.left.hr.analysis.model.mean[i],4)}} / {{fmt(result.left.hr.analysis.model.sd[i],4)}}</td><td>{{fmt(result.right.hr.analysis.model.mean[i],4)}} / {{fmt(result.right.hr.analysis.model.sd[i],4)}}</td><td>{{result.guide[key]}}</td></tr></tbody></table><p class="notice">{{result.guide.sd}}. {{result.guide.interpretation}}. Differenze tra parametri non dimostrano differenze nello stato di forma.</p><div class="form-grid"><div v-for="side in ['left','right']"><h3>{{side==='left'?'Primo':'Secondo'}} atleta · contesto</h3><p>{{result[side].split.train.length}} attività train · {{result[side].domain.samples}} campioni</p><p>{{result[side].train_period.map(date).join(' – ')}}</p><p>Potenza {{fmt(result[side].domain.power_quantiles_w[0])}}–{{fmt(result[side].domain.power_quantiles_w[4])}} W</p><p>A {{fmt(result[side].hr.analysis.B_reference.A)}} bpm · HR0 {{fmt(result[side].hr.analysis.HR0_reference.mean)}} bpm</p><details><summary>Incertezza media, durate e configurazione</summary><pre>{{JSON.stringify({ci95:result[side].hr.analysis.model.mean_ci95,domain:result[side].domain,config:result[side].config},null,2)}}</pre></details></div></div></div></template><div v-else class="empty"><h2>Confronti con un contesto.</h2><p>Scegli due atleti con una versione identificata.<br>Nessun ranking o interpretazione fisiologica automatica.</p></div></template>
